83,"Create a Python script that takes three command-line arguments: the path to an input CSV file, the path to an output CSV file, and a string containing a set of transformation rules. The script should read the input CSV file, apply the specified rules to transform the data, and then write the transformed data to the output CSV file. The rules can include operations such as filtering rows based on specific conditions, modifying column values, or rearranging columns. The script should utilize standard library functions and dynamically allocate memory as necessary.",120,,"['```python
import csv
import sys

def apply_rules(row, rules):
    for rule in rules:
        if '=' in rule:
            key, value = rule.split('=')
            row[key] = value
        elif 'filter' in rule:
            condition = eval(rule.replace('filter', ''), {'row': row})
            if not condition:
                return None
    return row

def transform_csv(input_path, output_path, rules):
    with open(input_path, mode='r', newline='') as infile, \
         open(output_path, mode='w', newline='') as outfile:

        reader = csv.DictReader(infile)
        fieldnames = reader.fieldnames
        writer = csv.DictWriter(outfile, fieldnames=fieldnames)

        writer.writeheader()
        for row in reader:
            transformed_row = apply_rules(row, rules)
            if transformed_row is not None:
                writer.writerow(transformed_row)

if __name__ == ""__main__"":
    if len(sys.argv) != 4:
        print(""Usage: python transform_csv.py <input_path> <output_path> <rules>"")
        sys.exit(1)

    input_path = sys.argv[1]
    output_path = sys.argv[2]
    rules = sys.argv[3].split(',')

    transform_csv(input_path, output_path, rules)
