0,"Create a Python class for a stack using arrays, with methods for initialization, pushing elements, popping elements, and peeking at the top element without removal. Handle stack underflow and overflow appropriately.",377,,"['```python
class Stack:
    def __init__(self, capacity):
        self.capacity = capacity
        self.stack = []

    def push(self, item):
        if len(self.stack) == self.capacity:
            raise OverflowError(""Stack is full"")
        self.stack.append(item)

    def pop(self):
        if not self.stack:
            raise UnderflowError(""Stack is empty"")
        return self.stack.pop()

    def peek(self):
        if not self.stack:
            raise UnderflowError(""Stack is empty"")
        return self.stack[-1]

# Example usage
try:
    my_stack = Stack(3)
    my_stack.push(10)
    my_stack.push(20)
    my_stack.push(30)
    print(my_stack.peek())  # Output: 30
    print(my_stack.pop())   # Output: 30
    print(my_stack.pop())   # Output: 20
    print(my_stack.pop())   # Output: 10
    print(my_stack.pop())   # Raises UnderflowError
except Exception as e:
    print(e)
```']",0,[0],[],True,0,0,0,

