from flask import Flask, request, jsonify

app = Flask(__name__)

# Mock database of resources
resources = {
    '1': {'id': '1', 'name': 'Resource 1', 'value': 10},
    '2': {'id': '2', 'name': 'Resource 2', 'value': 20}
}

@app.route('/resource/<resource_id>', methods=['PATCH'])
def update_resource(resource_id):
    resource = resources.get(resource_id)
    if not resource:
        return jsonify({'error': 'Resource not found'}), 404

    patch_data = request.get_json()
    resource.update(patch_data)

    return jsonify(resource)

@app.route('/resource/<resource_id>', methods=['DELETE'])
def delete_resource(resource_id):
    resource = resources.pop(resource_id, None)
    if not resource:
        return jsonify({'error': 'Resource not found'}), 404

    default_resource = {'id': resource_id, 'name': 'Deleted', 'value': 0}
    resources[resource_id] = default_resource

    return jsonify(default_resource)

if __name__ == '__main__':
    app.run(debug=True)
