import os
import re

def extract_sequence_numbers(file_path):
    try:
        with open(file_path, 'r') as file:
            lines = file.readlines()
            if not lines:
                return []

            last_line = lines[-1]
            sequence_numbers = re.findall(r'\d+', last_line)
            return [int(num) for num in sequence_numbers]
    except FileNotFoundError:
        print(f""File '{file_path}' not found."")
        return []
    except Exception as e:
        print(f""An error occurred: {e}"")
        return []

def sort_sequence_numbers(sequence_numbers):
    try:
        sorted_numbers = sorted(sequence_numbers, reverse=True)
        return sorted_numbers
    except TypeError as e:
        print(f""Invalid sequence numbers: {e}"")
        return []
