def transform_reduce(iterable, transform_func, initial=None):
    try:
        if initial is None:
            result = next(iterable)
        else:
            result = initial

        for element in iterable:
            result = transform_func(result, element)

        return result
    except StopIteration:
        raise ValueError(""The iterable is empty and no initial value was provided."")
    except Exception as e:
        raise RuntimeError(f""An error occurred: {e}"")

