from collections import Counter

class EnhancedWordCounter:
    def __init__(self, stop_words=None, sort_by=""descending""):
        self.stop_words = stop_words if stop_words is not None else set()
        self.sort_by = sort_by

    def count_words(self, words):
        word_counter = Counter(word for word in words if word.lower() not in self.stop_words)
        return word_counter

    def top_n_words(self, word_counts, n):
        sorted_words = sorted(word_counts.items(), key=lambda x: x[1], reverse=self.sort_by == ""descending"")
        return sorted_words[:n]
