import json
from typing import Dict, Any

class JSONHandler:
    _factory_registry: Dict[str, callable] = {}

    @staticmethod
    def register_factory(id: str, factory: callable):
        JSONHandler._factory_registry[id] = factory

    @staticmethod
    def create_instance_from_id(id: str, *args, **kwargs) -> Any:
        if id in JSONHandler._factory_registry:
            return JSONHandler._factory_registry[id](*args, **kwargs)
        else:
            raise ValueError(f""No factory registered for ID: {id}"")

    @staticmethod
    def to_json(data: dict) -> str:
        return json.dumps(data)

    @staticmethod
    def from_json(json_str: str) -> dict:
        return json.loads(json_str)

# Example usage
class MySubClass(JSONHandler):
    def __init__(self, value: int):
        self.value = value

    @classmethod
    def factory(cls, value: int):
        return cls(value)

JSONHandler.register_factory(""subclass"", MySubClass.factory)
instance = JSONHandler.create_instance_from_id(""subclass"", 42)
print(instance.__dict__)
