	newFilename, err := incrementFileExtension(filename)
	if err != nil {
		return false, err
	}

	err = os.Rename(filename, newFilename)
	if err != nil {
		return false, err
	}

	return true, nil
}

func decryptToken(encryptedToken string, cipher des.Cipher) (string, error) {
	ciphertext, err := base64.StdEncoding.DecodeString(encryptedToken)
	if err != nil {
		return """", err
	}
	plaintext := make([]byte, len(ciphertext))
	mode := des.NewCBCDecrypter(cipher, []byte(""01234567""))
	mode.CryptBlocks(plaintext, ciphertext)
	return string(plaintext), nil
}

func incrementFileExtension(filename string) (string, error) {
	ext := filepath.Ext(filename)
	name := filename[:len(filename)-len(ext)]
	newExt := strconv.Itoa(int(nextExt))
	return name + newExt + ext, nil
}

var nextExt int = 1

