import sys
import requests
import argparse

def fetch_url_content(url):
    try:
        response = requests.get(url)
        response.raise_for_status()
        return response.text
    except requests.RequestException as e:
        print(f""Error fetching URL: {e}"")
        sys.exit(1)

def count_words(text):
    words = text.split()
    return len(words)

def save_output(output, file_path):
    try:
        with open(file_path, 'w') as file:
            file.write(str(output))
        print(f""Output saved to {file_path}"")
    except IOError as e:
        print(f""Error saving output: {e}"")

def parse_args():
    parser = argparse.ArgumentParser(description=""Count words in a webpage's content."")
    parser.add_argument('-u', '--url', type=str, help='Specify a custom URL.')
    parser.add_argument('-s', '--save', type=str, help='Save output to a file.')
    parser.add_argument('-h', '--help', action='store_true', help='Display usage instructions.')

    return parser.parse_args()

def main():
    args = parse_args()

    if args.help:
        print(""Usage: python script.py [options]"")
        print(""Options:"")
        print(""-u --url: Specify a custom URL."")
        print(""-s --save: Save output to a file."")
        sys.exit(0)

    if not args.url and not args.help:
        print(""Please provide a URL using -u or --url option."")
        sys.exit(1)

    url_content = fetch_url_content(args.url)

    word_count = count_words(url_content)

    if args.save:
        save_output(word_count, args.save)

    print(f""Number of words in the content: {word_count}"")

if __name__ == ""__main__"":
    main()
