0,"Design and implement a program that manages a dynamic list of data structures representing user sessions in a network communication system. Each session data structure should contain the session ID, the corresponding IP address, and a flag indicating the status of the connection. The program should allow for adding new sessions to the list, removing existing sessions, updating session status, and listing all current sessions. Implement error handling for invalid inputs and ensure efficient memory management for scalability.",680,,"['```python
class UserSession:
    def __init__(self, session_id, ip_address, status):
        self.session_id = session_id
        self.ip_address = ip_address
        self.status = status

class SessionManager:
    def __init__(self):
        self.sessions = {}

    def add_session(self, session_id, ip_address, status):
        if session_id in self.sessions:
            raise ValueError(""Session ID already exists."")
        new_session = UserSession(session_id, ip_address, status)
        self.sessions[session_id] = new_session
        print(f""Session {session_id} added."")

    def remove_session(self, session_id):
        if session_id not in self.sessions:
            raise KeyError(""Session ID does not exist."")
        del self.sessions[session_id]
        print(f""Session {session_id} removed."")

    def update_status(self, session_id, new_status):
        if session_id not in self.sessions:
            raise KeyError(""Session ID does not exist."")
        self.sessions[session_id].status = new_status
        print(f""Status of Session {session_id} updated to {new_status}."")

    def list_sessions(self):
        for session_id, session in self.sessions.items():
            print(f""Session ID: {session.session_id}, IP Address: {session.ip_address}, Status: {session.status}"")

# Example usage:
session_manager = SessionManager()
session_manager.add_session(""123"", ""192.168.1.1"", ""active"")
session_manager.update_status(""123"", ""inactive"")
session_manager.list_sessions()
session_manager.remove_session(""123"")
