0,"Create a web API endpoint that accepts two HTTP methods: POST and PUT. The POST method should add a new item to the database, including validation for required fields and error handling for invalid input. The PUT method should update an existing item by its unique identifier, allowing only specified fields to be modified, and return the updated item if successful.",352,,"[""```python
from flask import Flask, request, jsonify
from flask_sqlalchemy import SQLAlchemy

app = Flask(__name__)
app.config['SQLALCHEMY_DATABASE_URI'] = 'sqlite:///items.db'
db = SQLAlchemy(app)

class Item(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    name = db.Column(db.String(80), nullable=False)
    description = db.Column(db.String(120))

@app.route('/item', methods=['POST'])
def create_item():
    data = request.get_json()
    if 'name' not in data or not data['name']:
        return jsonify({'error': 'Name is required'}), 400
    item = Item(name=data['name'], description=data.get('description'))
    db.session.add(item)
    db.session.commit()
    return jsonify(item.to_dict()), 201

@app.route('/item/<int:id>', methods=['PUT'])
def update_item(id):
    data = request.get_json()
    item = Item.query.get_or_404(id)
    if 'name' in data:
        item.name = data['name']
    if 'description' in data:
        item.description = data.get('description')
    db.session.commit()
    return jsonify(item.to_dict())

if __name__ == '__main__':
    app.run(debug=True)
