import logging
import yaml

# === Custom utility module ===
def read_yaml(file_path):
    with open(file_path, 'r') as file:
        try:
            return yaml.safe_load(file)
        except yaml.YAMLError as exc:
            print(f""Error in YAML file: {exc}"")
        except FileNotFoundError:
            print(f""File not found: {file_path}"")

def calculate_stats(data):
    if not data:
        raise ValueError(""Data cannot be empty"")

    total = sum(data.values())
    return {
        ""total"": total,
        ""average"": total / len(data)
    }

# === Personalized exception handler ===
class CustomException(Exception):
    def __init__(self, message):
        self.message = message
        super().__init__(self.message)

class DataEmptyError(CustomException):
    pass

# === Logging configuration with YAML file ===
def setup_logger(config_file='logging.yaml'):
    try:
        config = read_yaml(config_file)

        log_level = config.get('log_level', 'INFO')

        logging.basicConfig(level=log_level,
                            format='%(asctime)s - %(levelname)s - %(message)s',
                            handlers=[logging.FileHandler('app.log'),
                                      logging.StreamHandler()])

    except CustomException as e:
        print(f""Error setting up logger: {e}"")

# === Main script ===
if __name__ == ""__main__"":
    setup_logger()

    data = {'a': 1, 'b': 2, 'c': 3}

    try:
        stats = calculate_stats(data)

        logging.info(f""Calculated statistics: {stats}"")

    except DataEmptyError as e:
        logging.error(e)
