0,"Design a Python program using the asyncio library to manage the concurrent execution of multiple sorting algorithms. The program should accept command-line arguments specifying different sorting methods and their parameters. Based on user input, the program will dynamically select and apply the desired sorting algorithm to a list of elements, displaying the sorted output in real-time. Implement at least three distinct sorting algorithms, including QuickSort, MergeSort, and BubbleSort, each with its own implementation function. The program should also include a function to list all available sorting methods along with their names and parameters.",323,,"['```python
import asyncio
import sys

def quicksort(arr):
    if len(arr) <= 1:
        return arr
    pivot = arr[len(arr) // 2]
    left = [x for x in arr if x < pivot]
    middle = [x for x in arr if x == pivot]
    right = [x for x in arr if x > pivot]
    return quicksort(left) + middle + quicksort(right)

async def async_quicksort(arr):
    return await asyncio.to_thread(quicksort, arr)

def mergesort(arr):
    if len(arr) <= 1:
        return arr
    mid = len(arr) // 2
    left = arr[:mid]
    right = arr[mid:]
    return merge(await asyncio.gather(async_quicksort(left), async_quicksort(right)))

async def async_mergesort(arr):
    return await asyncio.to_thread(mergesort, arr)

def bubblesort(arr):
    n = len(arr)
    for i in range(n):
        for j in range(0, n - i - 1):
            if arr[j] > arr[j + 1]:
                arr[j], arr[j + 1] = arr[j + 1], arr[j]
    return arr

async def async_bubblesort(arr):
    return await asyncio.to_thread(bubblesort, arr)

def list_sorting_methods():
    methods = {
        ""quicksort"": quicksort,
        ""mergesort"": mergesort,
        ""bubblesort"": bubblesort
    }
    for method_name, _ in methods.items():
        print(f""{method_name}: {method_name}"")

if __name__ == ""__main__"":
    if len(sys.argv) < 3:
        print(""Usage: python script.py [sort_method] [list_elements]"")
        list_sorting_methods()
    else:
        sort_method = sys.argv[1]
        elements = list(map(int, sys.argv[2].split(',')))
        methods = {
            ""quicksort"": async_quicksort,
            ""mergesort"": async_mergesort,
            ""bubblesort"": async_bubblesort
        }
        if sort_method in methods:
            sorted_arr = asyncio.run(methods[sort_method](elements))
            print(f""Sorted array: {sorted_arr}"")
        else:
            print(""Invalid sorting method. Available methods:"")
            list_sorting_methods()
```']",0,[0],[],True,0,0,0,

