import argparse
from configparser import ConfigParser

def parse_config(file_path):
    config = ConfigParser()
    config.read(file_path)
    return config

def validate_config(config):
    required_sections = ['Server', 'Database']
    for section in required_sections:
        if not config.has_section(section):
            print(f""Error: Missing section '{section}'"")
            return False
        required_params = {
            'Server': ['address'],
            'Database': ['host', 'user', 'password']
        }
        for param in required_params[section]:
            if not config.has_option(section, param):
                print(f""Error: Missing parameter '{param}' in section '{section}'"")
                return False
    return True

def main():
    parser = argparse.ArgumentParser(description='Configuration File Validator')
    parser.add_argument('config_file', help='Path to the configuration file')
    args = parser.parse_args()

    config = parse_config(args.config_file)
    if validate_config(config):
        print(""Configuration file is valid."")
    else:
        print(""Configuration file contains errors."")

if __name__ == ""__main__"":
    main()
