0,"Create a Python program that accepts a user-input string containing space-separated floating-point numbers. Convert this string into a list of floats, then find and output the smallest number using an auxiliary function. Ensure the script handles invalid inputs, such as non-numeric strings or multiple spaces, by prompting for correct input and exiting with an error code if necessary. The program should also sort the list in ascending order before identifying the minimum value. Additionally, it should compute and display the average of all numbers in the list. The script should offer options for further analysis, including finding the maximum number, median value, or standard deviation of the input list.",242,,"['```python
import sys

def get_valid_input():
    while True:
        user_input = input(""Enter space-separated floating-point numbers: "")
        try:
            return [float(num) for num in user_input.split() if float(num)]
        except ValueError:
            print(""Invalid input! Please enter numeric values separated by spaces."")

def find_min(numbers):
    return min(numbers)

def sort_numbers(numbers):
    return sorted(numbers)

def calculate_average(numbers):
    return sum(numbers) / len(numbers)

def find_max(numbers):
    return max(numbers)

def find_median(numbers):
    numbers_sorted = sort_numbers(numbers)
    n = len(numbers_sorted)
    if n % 2 == 1:
        return numbers_sorted[n // 2]
    else:
        return (numbers_sorted[n // 2 - 1] + numbers_sorted[n // 2]) / 2

def calculate_standard_deviation(numbers):
    avg = calculate_average(numbers)
    variance = sum((x - avg) ** 2 for x in numbers) / len(numbers)
    return variance ** 0.5

def main():
    numbers = get_valid_input()
    sorted_numbers = sort_numbers(numbers)

    print(f""Sorted Numbers: {sorted_numbers}"")
    print(f""Minimum: {find_min(sorted_numbers)}"")
    print(f""Maximum: {find_max(sorted_numbers)}"")
    print(f""Average: {calculate_average(sorted_numbers)}"")
    print(f""Median: {find_median(sorted_numbers)}"")
    print(f""Standard Deviation: {calculate_standard_deviation(numbers)}"")

if __name__ == ""__main__"":
    main()
