1,"Create a Python program with a custom linked list class implementing bubble sort. Include namespace, class with methods for initializing, adding nodes, and sorting the list, and a destructor. The linked list class should efficiently manage nodes using pointers. Bubble sort should be a static method within the class, taking the head of the list as a parameter and sorting it in ascending order.",335,,"['```python
class LinkedList:
    def __init__(self):
        self.head = None

    def append(self, value):
        if not self.head:
            self.head = Node(value)
        else:
            current = self.head
            while current.next:
                current = current.next
            current.next = Node(value)

    @staticmethod
    def bubble_sort(head):
        if not head or not head.next:
            return head

        swapped = True
        while swapped:
            swapped = False
            current = head
            while current.next:
                if current.value > current.next.value:
                    current.value, current.next.value = current.next.value, current.value
                    swapped = True
                current = current.next
        return head

    def __del__(self):
        self.head = None


class Node:
    def __init__(self, value=0, next=None):
        self.value = value
        self.next = next
