from flask import Flask, request, jsonify, abort
from flask_sqlalchemy import SQLAlchemy
from flask_jwt_extended import JWTManager, jwt_required, create_access_token, get_jwt_identity
import redis
from functools import wraps

app = Flask(__name__)
app.config['SQLALCHEMY_DATABASE_URI'] = 'sqlite:///items.db'
app.config['JWT_SECRET_KEY'] = 'your-secret-key'
app.config['REDIS_URL'] = 'redis://localhost:6379/0'

db = SQLAlchemy(app)
jwt = JWTManager(app)
cache = redis.Redis.from_url(app.config['REDIS_URL'])

class Item(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    name = db.Column(db.String(80), nullable=False)
    owner_id = db.Column(db.Integer, db.ForeignKey('user.id'), nullable=False)

class User(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    username = db.Column(db.String(80), unique=True, nullable=False)
    items = db.relationship('Item', backref='owner')

@app.route('/items', methods=['POST'])
@jwt_required()
def add_item():
    # Rate limiting
    user_ip = request.remote_addr
    rate_limit_key = f""rate_limit:{user_ip}""
    if cache.get(rate_limit_key):
        abort(429, description=""Rate limit exceeded"")

    data = request.json
    if not data or 'name' not in data:
        abort(400, description=""Bad request"")

    item = Item(name=data['name'], owner_id=get_jwt_identity())
    db.session.add(item)
    try:
        db.session.commit()
    except Exception as e:
        db.session.rollback()
        abort(500, description=str(e))

    # Increment rate limit counter
    cache.incr(rate_limit_key)
    cache.expire(rate_limit_key, 60)  # 1 minute

    return jsonify(item.id), 201

@app.route('/items/<int:item_id>', methods=['PUT'])
@jwt_required()
def update_item(item_id):
    item = Item.query.get_or_404(item_id)
    if item.owner_id != get_jwt_identity():
        abort(403, description=""Forbidden"")

    data = request.json
    if 'name' in data:
        item.name = data['name']

    try:
        db.session.commit()
    except Exception as e:
        db.session.rollback()
        abort(500, description=str(e))

    return jsonify(item.id), 200

@app.route('/items/<int:item_id>', methods=['PATCH'])
@jwt_required()
def partial_update_item(item_id):
    item = Item.query.get_or_404(item_id)
    if item.owner_id != get_jwt_identity():
        abort(403, description=""Forbidden"")

    data = request.json
    for key, value in data.items():
        setattr(item, key, value)

    try:
        db.session.commit()
    except Exception as e:
        db.session.rollback()
        abort(500, description=str(e))

    return jsonify(item.id), 200

@app.route('/items/<int:item_id>', methods=['DELETE'])
@jwt_required()
def delete_item(item_id):
    item = Item.query.get_or_404(item_id)
    if item.owner_id != get_jwt_identity():
        abort(403, description=""Forbidden"")

    db.session.delete(item)
    try:
        db.session.commit()
    except Exception as e:
        db.session.rollback()
        abort(500, description=str(e))

    return jsonify({""message"": ""Item deleted""}), 200

@app.route('/items', methods=['GET'])
@jwt_required()
def get_items():
    page = request.args.get('page', 1, type=int)
    per_page = request.args.get('per_page', 10, type=int)
    items = Item.query.paginate(page=page, per_page=per_page, error_out=False).items
    return jsonify([item.id for item in items]), 200

if __name__ == '__main__':
    db.create_all()
    app.run(debug=True)
