1,"Develop a function that processes a configuration file to retrieve the version number. The function should read the file, sort its content, extract the version number from the last line, and handle exceptions appropriately. The function should return the extracted version number and raise specific errors for cases where the file does not exist or cannot be processed.",94,,"['```python
import os

def get_version_from_config(file_path):
    try:
        with open(file_path, 'r') as file:
            lines = file.readlines()
            sorted_lines = sorted(lines)
            version_line = sorted_lines[-1].strip()
            if not version_line.startswith('Version:'):
                raise ValueError(""Invalid version format in the config file."")
            return version_line.split(': ')[1]
    except FileNotFoundError:
        raise FileNotFoundError(f""The configuration file '{file_path}' does not exist."")
    except Exception as e:
        raise Exception(f""An error occurred while processing the configuration file: {e}"")

# Example usage
try:
    version = get_version_from_config('config.txt')
    print(f""Extracted Version: {version}"")
except Exception as e:
    print(e)
