import json
import logging
import sys

# Define a class to handle the configuration
class ConfigManager:
    def __init__(self, config_path):
        self.config = {}
        self.load_config(config_path)

    def load_config(self, config_path):
        try:
            with open(config_path, 'r') as file:
                self.config = json.load(file)
                self.validate_config()
        except FileNotFoundError:
            logging.error(""Configuration file not found."")
            sys.exit(1)
        except json.JSONDecodeError:
            logging.error(""Invalid JSON format in the configuration file."")
            sys.exit(1)

    def validate_config(self):
        required_sections = ['input_output', 'custom_commands', 'server_addresses',
                             'database_credentials', 'app_settings', 'env_vars', 'logging']
        for section in required_sections:
            if section not in self.config:
                logging.error(f""Missing section: {section}"")
                sys.exit(1)

    def get_config(self):
