import hashlib
import random
import string

def generate_session_token(username):
    if not isinstance(username, str) or len(username) < 1:
        raise ValueError(""Invalid username format"")
    if len(username) > 3:
        session_token = username[:3] + ''.join(random.choices(string.hexdigits, k=5))
        return session_token
    else:
        raise ValueError(""Username too short"")

def compute_file_hash(filename, user):
    if not isinstance(user, str) or not isinstance(filename, str):
        raise TypeError(""Invalid input type"")

    try:
        session_token = generate_session_token(user)

        with open(filename, 'rb') as f:
            hash_obj = hashlib.md5()
            while True:
                data = f.read(4096)
                if not data:
                    break
                hash_obj.update(data)

            return hash_obj.hexdigest()

    except Exception as e:
        print(f""Error: {e}"")
