import sys
from pydub import AudioSegment

def main():
    if len(sys.argv) < 2:
        print(""Error: No input file specified."")
        print(""Usage: python script.py <input_file> [-v] [-s] [-o output_file]"")
        return

    input_file = sys.argv[1]
    try:
        audio_segment = AudioSegment.from_file(input_file)
    except Exception as e:
        print(f""Error: Unable to load the file. {e}"")
        return

    duration = len(audio_segment) / 1000
    print(f""Total duration of all audio clips in '{input_file}': {duration:.2f} seconds"")

    if len(sys.argv) > 2:
        commands = sys.argv[2:]
        if ""-v"" in commands:
            formats = set()
            for format_name, loader in AudioSegment.formats.items():
                try:
                    formats.add(loader.name)
                except Exception as e:
                    pass
            print(""Unique audio formats found:"", "", "".join(formats))

        if ""-s"" in commands:
            sorted_clips = []
            # Assuming we have a list of clips stored in 'clips'
            for clip in clips:
                sorted_clips.append((clip, len(clip) / 1000))
            sorted_clips.sort(key=lambda x: x[1])
            print(""Sorted audio clips by duration:"")
            for clip, dur in sorted_clips:
                print(f""{dur:.2f} seconds"")

        if ""-o"" in commands and len(commands) > commands.index(""-o"") + 1:
            output_file = commands[commands.index(""-o"") + 1]
            with open(output_file, ""w"") as f:
                for clip, dur in sorted_clips:
                    f.write(f""{dur:.2f} seconds\n"")
            print(f""Sorted list saved to '{output_file}'"")

if __name__ == ""__main__"":
    main()
