@app.route('/api/v1/array/put', methods=['PUT'])
def update_array():
    token = request.headers.get('Authorization')
    if not authenticate_user(token):
        return jsonify({""error"": ""Unauthorized""}), 401

    try:
        data = request.json
        new_value = data['value']
        condition = data['condition']  # e.g., 'above' or 'below'
        threshold = data['threshold']

        if not isinstance(new_value, int) or not (isinstance(threshold, int) and threshold > 0):
            return jsonify({""error"": ""Invalid input type""}), 400

        size = random.randint(10, 20)
        array = [random.randint(1, 50) for _ in range(size)]

        if condition == 'above':
            updated_array = [new_value if x > threshold else x for x in array]
        elif condition == 'below':
            updated_array = [new_value if x < threshold else x for x in array]
        else:
            return jsonify({""error"": ""Invalid condition""}), 400

        return jsonify(updated_array)

    except KeyError as e:
        return jsonify({""error"": f""Missing key: {e}""}), 400

@app.route('/api/v1/array/delete', methods=['DELETE'])
def delete_elements():
    token = request.headers.get('Authorization')
    if not authenticate_user(token):
        return jsonify({""error"": ""Unauthorized""}), 401

    try:
        data = request.json
        condition = data['condition']  # e.g., 'above' or 'below'
        threshold = data['threshold']

        if not isinstance(threshold, int) and threshold > 0:
            return jsonify({""error"": ""Invalid input type""}), 400

        size = random.randint(10, 20)
        array = [random.randint(1, 50) for _ in range(size)]

        if condition == 'above':
