from flask import Flask, request, jsonify
import requests

app = Flask(__name__)

@app.route('/validate_form', methods=['POST'])
def validate_form():
    data = request.json
    errors = []

    # Example validation: Check if the email field is empty
    if not data.get('email'):
        errors.append({'field': 'email', 'message': 'Email is required'})

    return jsonify({'valid': len(errors) == 0, 'errors': errors})

@app.route('/submit_form', methods=['POST'])
def submit_form():
    data = request.json

    # Example processing: Simulate a database query
    response = requests.get('https://api.example.com/data')

    if response.status_code == 200:
        return jsonify({'message': 'Form processed successfully'})
    else:
        return jsonify({'message': 'Error processing form'}), 500

if __name__ == '__main__':
    app.run(debug=True)
