import re
from datetime import datetime

# Define a class to handle package validation and categorization
class PackageValidator:
    def __init__(self):
        self.supported_languages = {
            'Python': r'^[a-zA-Z_][a-zA-Z0-9_]*$',
            'JavaScript': r'^[a-zA-Z_$][0-9a-zA-Z_$]*$',
            # Add other languages and their respective regex patterns here
        }

    def validate_package(self, package_name, language):
        if language in self.supported_languages:
            pattern = self.supported_languages[language]
            if re.match(pattern, package_name):
                return True
            else:
                print(f""Invalid package name '{package_name}' for {language}"")
                return False
        else:
            print(f""Unsupported language: {language}"")
            return False

    def categorize_packages(self, entries):
        categorized = {}
        for entry in entries:
            parts = entry.split()
            if len(parts) >= 2:
                package_name = parts[0]
                language = parts[1]
                version = parts[2] if len(parts) > 2 else None
                if self.validate_package(package_name, language):
                    if language not in categorized:
                        categorized[language] = []
                    categorized[language].append((package_name, version))
        return categorized

# Function to read entries from a file and process them
def process_file(filename):
    with open(filename, 'r') as file:
        entries = [line.strip() for line in file.readlines()]
    validator = PackageValidator()
    categorized_packages = validator.categorize_packages(entries)
    return categorized_packages

# Function to handle multiple files and output results
def batch_process_files(filenames):
    results = []
    for filename in filenames:
        result = process_file(filename)
        results.append((filename, result))
    return results

# Example usage
if __name__ == ""__main__"":
    input_files = ['packages1.txt', 'packages2.txt']  # List of input files to process
    processed_results = batch_process_files(input_files)

    for file, result in processed_results:
        print(f""Results from {file}:"")
        for language, packages in result.items():
            print(f""Language: {language}"")
            for package_name, version in packages:
                print(f""  Package Name: {package_name}, Version: {version}"")

# Logging function (simple example)
def log_activity(message):
    with open('log.txt', 'a') as log_file:
        timestamp = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
        log_file.write(f""{timestamp} - {message}\n"")

# Example usage of logging
log_activity(""Processing started"")
for file in input_files:
    log_activity(f""Processed file: {file}"")
log_activity(""Processing completed"")
```

