3,"Write a Python script that processes command line arguments to identify if a directory path is provided. If no directory path is given, the script should display usage instructions. If a directory path is provided, the script should traverse all files within the directory and count the total number of text lines across all files. The script should support options like --help, -v for verbose output, and -s for summarizing file names instead of full paths. Utilize standard library functions to accomplish this task.",121,,"['```python
import os
import sys

def count_lines_in_directory(directory_path):
    total_lines = 0
    for root, _, files in os.walk(directory_path):
        for file in files:
            if file.endswith('.txt'):
                with open(os.path.join(root, file), 'r') as f:
                    total_lines += sum(1 for line in f)
    return total_lines

def display_usage():
    print(""Usage: python script.py [options] <directory_path>"")
    print(""Options:"")
    print(""  --help, -h         Show help message and exit"")
    print(""  -v                 Enable verbose output"")
    print(""  -s                 Summarize file names instead of full paths"")

def main():
    if len(sys.argv) < 2:
        display_usage()
        sys.exit(1)

    options = []
    directory_path = None
    for arg in sys.argv[1:]:
        if arg.startswith('-'):
            options.append(arg)
        else:
            if directory_path is not None:
                display_usage()
                sys.exit(1)
            directory_path = arg

    verbose = '-v' in options
    summarize = '-s' in options

    if directory_path is None and '--help' not in options:
        print(""Error: Directory path must be provided."")
        display_usage()
        sys.exit(1)

    if '--help' in options:
        display_usage()
        sys.exit(0)

    total_lines = count_lines_in_directory(directory_path)

    if verbose:
        for root, _, files in os.walk(directory_path):
            for file in files:
                if file.endswith('.txt'):
                    with open(os.path.join(root, file), 'r') as f:
                        lines = sum(1 for line in f)
                        print(f""{os.path.join(root, file)}: {lines} lines"")
        print(f""Total lines across all text files: {total_lines}"")
    elif summarize:
        print(""Text files in directory:"")
        for root, _, files in os.walk(directory_path):
            for file in files:
                if file.endswith('.txt'):
                    print(os.path.join(root, file))
        print(f""Total lines across all text files: {total_lines}"")
    else:
        print(f""Total lines across all text files: {total_lines}"")

if __name__ == ""__main__"":
    main()
