import random
import string
import base64
from cryptography.hazmat.primitives import serialization
from cryptography.hazmat.primitives.asymmetric import rsa

class NFAPI_UE_DATA:
    def __init__(self, UE_ID, IMSI, NAS_MESSAGE):
        self.UE_ID = UE_ID
        self.IMSI = IMSI
        self.NAS_MESSAGE = NAS_MESSAGE

def generate_random_string(length=10):
    return ''.join(random.choices(string.ascii_letters + string.digits, k=length))

def generate_imsi():
    return '23410' + ''.join([str(random.randint(0, 9)) for _ in range(7)])

def encrypt_nas_message(message):
    key = rsa.generate_private_key(
        public_exponent=65537,
        key_size=2048,
    )
    pem = key.private_bytes(
        encoding=serialization.Encoding.PEM,
        format=serialization.PrivateFormat.TraditionalOpenSSL,
        encryption_algorithm=serialization.NoEncryption()
    )
    encrypted_message = base64.b64encode(pem)
    return encrypted_message

def fetch_certificate_details():
    # Placeholder for fetching certificate details
    return {
        'subject': 'CN=localhost',
        'issuer': 'CN=Certificate Authority'
    }

def create_pem_file(details, output_path):
    with open(output_path, 'w') as f:
        f.write(f""Subject: {details['subject']}\nIssuer: {details['issuer']}"")

def generate_nfaapi_ue_data(N, output_folder):
    nfaapi_data_list = []
    for _ in range(N):
        UE_ID = generate_random_string()
        IMSI = generate_imsi()
        NAS_MESSAGE = encrypt_nas_message('Sample NAS Message')
        nfaapi_data_list.append(NFAPI_UE_DATA(UE_ID, IMSI, NAS_MESSAGE))

        details = fetch_certificate_details()
        output_path = f""{output_folder}/{UE_ID}.pem""
        create_pem_file(details, output_path)

    return nfaapi_data_list

def main():
    N = 5
    output_folder = 'certificates'
    nfaapi_data_list = generate_nfaapi_ue_data(N, output_folder)
    for data in nfaapi_data_list:
        print(f""UE_ID: {data.UE_ID}, IMSI: {data.IMSI}, NAS_MESSAGE Length: {len(data.NAS_MESSAGE)}"")

if __name__ == ""__main__"":
    main()
