0,"Create a Python script that utilizes command-line arguments to execute operations on a CSV file. The script should be augmented to include functionalities for filtering and aggregating data based on specific criteria, while also incorporating error handling for file access and null input strings. This script will incorporate string manipulation, such as trimming, and will utilize delimiter-separated values for processing data. Additionally, the script should offer an option to output the processed data to a new CSV file with sorted or filtered records based on the user's choice of criteria.",121,,"['```python
import sys
import csv
from operator import itemgetter

def filter_data(data, column_index, value):
    return [row for row in data if row[column_index] == value]

def aggregate_data(data, aggregation_column):
    from collections import defaultdict
    aggregated = defaultdict(int)
    for row in data:
        aggregated[row[aggregation_column]] += 1
    return dict(aggregated)

def process_csv(input_file, output_file, filter_criteria=None, sort_by=None, aggregate_on=None):
    try:
        with open(input_file, mode='r', newline='') as infile:
            reader = csv.reader(infile)
            data = list(reader)

        if filter_criteria:
            column_name, value = filter_criteria.split('=')
            column_index = next(i for i, col in enumerate(data[0]) if col == column_name.strip())
            data = filter_data(data[1:], column_index, value)

        if aggregate_on is not None:
            aggregated_data = aggregate_data(data, int(aggregate_on))
            print(aggregated_data)
            return

        if sort_by is not None:
            column_name = sort_by
            column_index = next(i for i, col in enumerate(data[0]) if col == column_name.strip())
            data = sorted(data[1:], key=itemgetter(column_index))

        with open(output_file, mode='w', newline='') as outfile:
            writer = csv.writer(outfile)
            writer.writerows([data[0]] + data[1:])

    except FileNotFoundError:
        print(f""Error: The file {input_file} does not exist."")
    except IndexError:
        print(""Error: Invalid column index provided."")

if __name__ == ""__main__"":
    if len(sys.argv) < 4:
        print(""Usage: python script.py <input_file> <output_file> --filter=<column>=<value> --sort=<column> --aggregate=<column>"")
        sys.exit(1)

    input_file = sys.argv[1]
    output_file = sys.argv[2]

    filter_criteria = None
    sort_by = None
    aggregate_on = None

    for i in range(3, len(sys.argv), 2):
        option = sys.argv[i].strip()
        if option == ""--filter"":
            filter_criteria = sys.argv[i + 1]
        elif option == ""--sort"":
            sort_by = sys.argv[i + 1]
        elif option == ""--aggregate"":
            aggregate_on = sys.argv[i + 1]

    process_csv(input_file, output_file, filter_criteria, sort_by, aggregate_on)
