import hashlib
from cryptography.hazmat.primitives.asymmetric import ec
from cryptography.hazmat.primitives.kdf.hkdf import HKDF
from cryptography.hazmat.primitives.ciphers.aead import AESGCM, ChaCha20Poly1305
from cryptography.exceptions import InvalidKey

# 1. Secure Key Exchange using ECDH
def generate_key_pair():
    private_key = ec.generate_private_key(ec.SECP256R1())
    public_key = private_key.public_key()
    return private_key, public_key

def derive_shared_key(private_key, other_public_key):
    shared_secret = private_key.exchange(ec.ECDH(), other_public_key)
    hkdf = HKDF(
        algorithm=hashlib.sha256,
        length=32,
        salt=None,
        info=b'handshake data',
    )
    return hkdf.derive(shared_secret)

# 2. Cipher Suite Choice
def encrypt_message(cipher_suite, key, plaintext):
    if cipher_suite == 'AES-GCM':
        aes_gcm = AESGCM(key)
        nonce = os.urandom(12)
        ciphertext = aes_gcm.encrypt(nonce, plaintext, None)
        return {'nonce': nonce, 'ciphertext': ciphertext}
    elif cipher_suite == 'ChaCha20-Poly1305':
        chacha20_poly1305 = ChaCha20Poly1305(key)
        nonce = os.urandom(12)
        ciphertext = chacha20_poly1305.encrypt(nonce, plaintext, None)
        return {'nonce': nonce, 'ciphertext': ciphertext}
    else:
        raise ValueError(""Unsupported cipher suite"")

# 3. Integrity Verification
def verify_message(cipher_suite, key, message):
    if cipher_suite == 'AES-GCM':
        aes_gcm = AESGCM(key)
        try:
            plaintext = aes_gcm.decrypt(message['nonce'], message['ciphertext'], None)
            return plaintext
        except InvalidKey:
            raise ValueError(""Message integrity verification failed"")
    elif cipher_suite == 'ChaCha20-Poly1305':
        chacha20_poly1305 = ChaCha20Poly1305(key)
        try:
            plaintext = chacha20_poly1305.decrypt(message['nonce'], message['ciphertext'], None)
            return plaintext
        except InvalidKey:
            raise ValueError(""Message integrity verification failed"")
    else:
        raise ValueError(""Unsupported cipher suite"")

# 4. Security Violation Exceptions
def check_access(user_permissions, required_permission):
    if not user_permissions.get(required_permission):
        raise PermissionError(f""Access denied: {required_permission} permission is required"")

# 5. Performance Optimization
# (Already optimized for minimal computational overhead)

# 6. Testing Integration
import unittest

class TestEncryption(unittest.TestCase):
    def test_aes_gcm(self):
        private_key, public_key = generate_key_pair()
        shared_key = derive_shared_key(private_key, public_key)
        plaintext = b""Hello, secure world!""
        encrypted_message = encrypt_message('AES-GCM', shared_key, plaintext)
        decrypted_message = verify_message('AES-GCM', shared_key, encrypted_message)
        self.assertEqual(decrypted_message, plaintext)

    def test_chacha20_poly1305(self):
        private_key, public_key = generate_key_pair()
        shared_key = derive_shared_key(private_key, public_key)
        plaintext = b""Hello, secure world!""
        encrypted_message = encrypt_message('ChaCha20-Poly1305', shared_key, plaintext)
        decrypted_message = verify_message('ChaCha20-Poly1305', shared_key, encrypted_message)
        self.assertEqual(decrypted_message, plaintext)

