from collections import Counter

class EnhancedWordCounter:
    def __init__(self, stop_words=None, sort_by='descending'):
        self.stop_words = set(stop_words) if stop_words else set()
        self.sort_by = sort_by

    def count_words(self, words):
        word_counts = Counter(words)
        filtered_counts = {word: count for word, count in word_counts.items() if word not in self.stop_words}
        return filtered_counts

    def top_n_words(self, counts, n):
        sorted_counts = sorted(counts.items(), key=lambda x: x[1], reverse=(self.sort_by == 'descending'))
        return dict(sorted_counts[:n])
