import base64
import hashlib
import re

def merge_fsa_nfa_customer_profiles(filenames):
    valid_chars = r'[a-zA-Z0-9-_]'

    def sanitize_filename(filename):
        return ''.join(c for c in filename if re.match(valid_chars, c))

    def encode_validate(filename):
        encoded = base64.b64encode(filename.encode()).decode()
        hash_object = hashlib.sha1(encoded.encode())
        return encoded, hash_object.hexdigest()

    states = []

    for filename in filenames:
        sanitized_filename = sanitize_filename(filename)
        encoded, hash_value = encode_validate(sanitized_filename)

        # Simulate state structure
        state = {
            'filename': sanitized_filename,
            'encoded': encoded,
            'hash': hash_value
        }

        states.append(state)

    return states

# Example usage:
